import{Z as t,e as a,f as o,a0 as i}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Templating","description":"","frontmatter":{},"headers":[],"relativePath":"guides/templating-theming/index.md","filePath":"guides/templating-theming/index.md","lastUpdated":1782532814000}'),r={name:"guides/templating-theming/index.md"};function n(s,e,d,l,m,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="templating" tabindex="-1">Templating <a class="header-anchor" href="#templating" aria-label="Permalink to &quot;Templating&quot;">​</a></h1><p>Twig templates, theme config, success pages, and front-end rendering patterns.</p><h2 id="add-floating-labels-to-your-form-fields" tabindex="-1"><a href="/guides/templating-theming/add-floating-labels-to-your-form-fields">Add Floating Labels to Your Form Fields</a> <a class="header-anchor" href="#add-floating-labels-to-your-form-fields" aria-label="Permalink to &quot;[Add Floating Labels to Your Form Fields](/guides/templating-theming/add-floating-labels-to-your-form-fields)&quot;">​</a></h2><p>Floating labels sit inside the input and animate out of the way when the user focuses or enters a value — similar to <a href="https://getbootstrap.com/docs/5.3/forms/floating-labels/" target="_blank" rel="noreferrer">Bootstrap&#39;s form-floating pattern</a>. This guide adds floating labels as an opt-in label position editors can choose per field, without forking every field template.</p><h2 id="build-a-success-page-for-your-form" tabindex="-1"><a href="/guides/templating-theming/build-a-success-page-for-your-form">Build a Success Page for Your Form</a> <a class="header-anchor" href="#build-a-success-page-for-your-form" aria-label="Permalink to &quot;[Build a Success Page for Your Form](/guides/templating-theming/build-a-success-page-for-your-form)&quot;">​</a></h2><p>After submit, Formie can show a message, hide the form, or redirect elsewhere. A dedicated success page lets you thank the user and show what they entered — useful for confirmations, gated content, or support requests.</p><h2 id="building-a-pdf-template-from-scratch" tabindex="-1"><a href="/guides/templating-theming/building-a-pdf-template-from-scratch">Building a PDF Template from Scratch</a> <a class="header-anchor" href="#building-a-pdf-template-from-scratch" aria-label="Permalink to &quot;[Building a PDF Template from Scratch](/guides/templating-theming/building-a-pdf-template-from-scratch)&quot;">​</a></h2><p>PDF templates let Formie attach a generated PDF when an email notification sends — useful for invoices, certificates, signed agreements, or printable summaries. This guide walks through creating a PDF template from scratch and attaching it to a notification.</p><h2 id="create-a-content-managed-user-registration-form-with-formie" tabindex="-1"><a href="/guides/templating-theming/create-a-content-managed-user-registration-form-with-formie">Create a Content-Managed User Registration Form with Formie</a> <a class="header-anchor" href="#create-a-content-managed-user-registration-form-with-formie" aria-label="Permalink to &quot;[Create a Content-Managed User Registration Form with Formie](/guides/templating-theming/create-a-content-managed-user-registration-form-with-formie)&quot;">​</a></h2><p>Formie can content-manage Craft-native forms — login, registration, password reset, and profile updates — so clients can edit labels, instructions, and field order in the form builder. Registration is a common starting point.</p><h2 id="create-a-gated-download-page-for-your-form" tabindex="-1"><a href="/guides/templating-theming/create-a-gated-download-page-for-your-form">Create a Gated Download Page for Your Form</a> <a class="header-anchor" href="#create-a-gated-download-page-for-your-form" aria-label="Permalink to &quot;[Create a Gated Download Page for Your Form](/guides/templating-theming/create-a-gated-download-page-for-your-form)&quot;">​</a></h2><p>Create a private resource download for signed-in visitors. The walkthrough checks submission ownership in a controller and streams a file from private storage.</p><h2 id="custom-templating-for-repeater-fields" tabindex="-1"><a href="/guides/templating-theming/custom-templating-for-repeater-fields">Custom Templating for Repeater Fields</a> <a class="header-anchor" href="#custom-templating-for-repeater-fields" aria-label="Permalink to &quot;[Custom Templating for Repeater Fields](/guides/templating-theming/custom-templating-for-repeater-fields)&quot;">​</a></h2><p>Repeater fields let users add and remove rows of nested fields. Most projects can style them with <a href="/reference/theme-tag-reference#repeater-field">theme config</a>, but when you need different markup — a card layout, a custom add/remove control, or tighter integration with your design system — template overrides are the right tool.</p><h2 id="how-to-conditionally-redirect-users-based-on-their-input" tabindex="-1"><a href="/guides/templating-theming/how-to-conditionally-redirect-users-based-on-their-input">How to Conditionally Redirect Users Based on Their Input</a> <a class="header-anchor" href="#how-to-conditionally-redirect-users-based-on-their-input" aria-label="Permalink to &quot;[How to Conditionally Redirect Users Based on Their Input](/guides/templating-theming/how-to-conditionally-redirect-users-based-on-their-input)&quot;">​</a></h2><p>Sometimes the thank-you destination should depend on what the user submitted — send opted-in users to one URL and everyone else to another, route by department, or branch on a quiz score. Formie supports this natively with <strong>Redirect Rules</strong>; the patterns below cover cases where you need more control.</p><h2 id="how-to-manually-set-the-page-for-a-form" tabindex="-1"><a href="/guides/templating-theming/how-to-manually-set-the-page-for-a-form">How to Manually Set the Page for a Form</a> <a class="header-anchor" href="#how-to-manually-set-the-page-for-a-form" aria-label="Permalink to &quot;[How to Manually Set the Page for a Form](/guides/templating-theming/how-to-manually-set-the-page-for-a-form)&quot;">​</a></h2><p>Multi-page forms usually progress in order, but sometimes you want to land users on a specific page — for example, skipping introductory questions when they arrive from a campaign link, or offering a &quot;commercial enquiry&quot; entry point alongside a residential one.</p><h2 id="the-complete-guide-to-rendering-submission-content" tabindex="-1"><a href="/guides/templating-theming/the-complete-guide-to-rendering-submission-content">The Complete Guide to Rendering Submission Content</a> <a class="header-anchor" href="#the-complete-guide-to-rendering-submission-content" aria-label="Permalink to &quot;[The Complete Guide to Rendering Submission Content](/guides/templating-theming/the-complete-guide-to-rendering-submission-content)&quot;">​</a></h2><p>Querying submissions, field-type recipes, and common mistakes when outputting stored values. Method reference and Twig/PHP examples live in <a href="/developers/submission-content">Submission Content</a>.</p><h2 id="theme-config-for-a-design-system" tabindex="-1"><a href="/guides/templating-theming/theme-config-for-a-design-system">Theme Config for a Design System</a> <a class="header-anchor" href="#theme-config-for-a-design-system" aria-label="Permalink to &quot;[Theme Config for a Design System](/guides/templating-theming/theme-config-for-a-design-system)&quot;">​</a></h2><p>If your site uses a design system — Tailwind utilities, Bootstrap components, or shared BEM classes — theme config is usually the best way to align Formie forms with it. You define HTML tags and attributes once, then reuse that configuration across every form.</p>',22)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
